// Generated by Selenium IDE
import { Builder, By, Key } from 'selenium-webdriver';
import assert from 'assert';

describe('Register', function() {
  this.timeout(30000)
  let driver
  let vars
  beforeEach(async function() {
    driver = await new Builder().forBrowser('firefox').build()
    vars = {}
  })
  afterEach(async function() {
    await driver.quit();
  })
  it('only_email', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Email")).click()
    vars["namal@test.com"] = await driver.findElement(By.id("Email")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('only_fullname', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Name")).click()
    vars["Namal Perera"] = await driver.findElement(By.id("Name")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('only_password', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Password")).click()
    vars["namal123$"] = await driver.findElement(By.id("Password")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('only_re_password', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Re-Enter Password")).click()
    await driver.findElement(By.id("Re-Enter Password")).sendKeys("namal123$")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('only_fullname_re_pw', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Name")).click()
    await driver.findElement(By.id("Name")).sendKeys(Key.DOWN)
    await driver.findElement(By.id("Name")).sendKeys("Namal Perera")
    await driver.findElement(By.id("Re-Enter Password")).click()
    await driver.findElement(By.id("Re-Enter Password")).sendKeys("namal123%")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('ony_fullname_password', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Name")).click()
    await driver.findElement(By.id("Name")).sendKeys("Namal Perera")
    await driver.findElement(By.id("Password")).click()
    await driver.findElement(By.id("Password")).sendKeys("namal123%")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('onlt_email_and_fullname', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Name")).click()
    await driver.findElement(By.id("Name")).sendKeys("Namal Perera")
    await driver.findElement(By.id("Email")).click()
    await driver.findElement(By.id("Email")).sendKeys("namal@test.com")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
  it('correct_details', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Name")).click()
    vars["Namal Perera"] = await driver.findElement(By.id("Name")).getAttribute("value")
    await driver.findElement(By.id("Email")).click()
    vars["namal@test.com"] = await driver.findElement(By.id("Email")).getAttribute("value")
    await driver.findElement(By.id("Password")).click()
    vars["Namal$123"] = await driver.findElement(By.id("Password")).getAttribute("value")
    await driver.findElement(By.id("Re-Enter Password")).click()
    vars["Namal$123"] = await driver.findElement(By.id("Re-Enter Password")).getAttribute("value")
    await driver.findElement(By.css(".rounded-xl")).click()
    assert(await driver.getTitle() == "Kannangara Hardwares")
  })
  it('invaid_email', async function() {
    await driver.get("http://localhost:5173/register")
    await driver.manage().window().setRect({ width: 1056, height: 693 })
    await driver.findElement(By.id("Email")).click()
    await driver.findElement(By.id("Email")).sendKeys("kjhdfjgkfjv")
    await driver.findElement(By.css(".rounded-xl")).click()
  })
})
